  12  * This function is now more intelligent, handling hierarchy and preserving existing IDs and properties.
  13  *
  14  * @param markdown The raw markdown string to parse.
  15  * @param existingContent The current project content to preserve IDs and properties.
  16  * @param isToc Only parse structure (headings, lists), ignore other content.
  17  * @returns An array of Chapter and Section objects.
  18  */
  19 export function parseMarkdownToContent(markdown: string, existingContent: ProjectContent, isToc: boolean = false): ProjectContent {
  20   const ast = unified().use(remarkParse).use(remarkGfm).parse(markdown) as MdastRoot;
  21   const newContent: (Chapter | Section)[] = [];
  22   let currentChapter: Chapter | null = null;
  23   let currentSection: Section | null = null;
  24   let accumulatedContent: RootContent[] = [];
  25   const usedIds = new Set<string>(); // Keep track of used IDs to avoid duplicates
  26 
  27   const findExistingItem = <T extends Chapter | Section>(title: string, collection: ProjectContent, constructor: { new(props: any): T }): T | undefined => {
  28     for (const item of collection) {
  29         if (item instanceof constructor && item.title === title && !usedIds.has(item.id)) {
  30             return item as T;
  31         }
  32         if (item instanceof Chapter) {
  33             const foundInSection = item.sections.find(section => section.title === title && !usedIds.has(section.id));
  34             if (foundInSection && constructor === Section) {
  35                 return foundInSection as T;
  36             }
  37         }
  38     }
  39     return undefined;
  40   };
  41 
  42   const flushSection = () => {
  43     if (currentSection) {
  44       const sectionMarkdown = isToc ? (currentSection.content || '') : unified().use(remarkGfm).use(remarkStringify).stringify({ type: 'root', children: accumulatedContent }).trim();
  45 
  46       const updatedSection = currentSection.withProps({ content: sectionMarkdown });
  47 
  48       if (currentChapter) {
  49         // addSection is immutable and returns a new Chapter instance
  50         currentChapter = currentChapter.addSection(updatedSection);
  51       } else {
  52         newContent.push(updatedSection);
  53       }
  54     }
  55     accumulatedContent = [];
  56   };
  57 
  58   const flushChapter = () => {
  59     flushSection();
  60     if (currentChapter) {
  61       newContent.push(currentChapter);
  62     }
  63     currentChapter = null;
  64   };
  65 
  66   // Process all nodes in the AST
  67   for (const node of ast.children) {
  68     if (node.type === 'heading') {
  69       const title = getNodeText(node).trim();
  70       if (node.depth === 1) { // Chapter
  71         flushChapter();
  72         const existingChapter = findExistingItem(title, existingContent, Chapter);
  73         currentChapter = new Chapter({ 
  74           id: existingChapter?.id, 
  75           title: title, 
  76           sections: [] // CRITICAL FIX: Always start with empty sections
  77         });
  78         if (existingChapter) usedIds.add(existingChapter.id);
