  91             guidelines: existingSection?.guidelines ? [...existingSection.guidelines] : [],
  92             constraints: existingSection?.constraints ? [...existingSection.constraints] : [],
  93             behaviors: existingSection?.behaviors ? [...existingSection.behaviors] : [],
  94             context: existingSection?.context,
  95         });
  96         if (existingSection) usedIds.add(existingSection.id);
  97       }
  98     } else if (node.type === 'list' && currentChapter && isToc) {
  99         for (const listItem of node.children) {
